WITH ops AS (SELECT DISTINCT op.ano_emissao,op.id_referencia_bacen,op.numero_ordem,op.cnpj_basico_instituicao_financeira FROM `basedosdados.br_bcb_sicor.operacao` op WHERE op.ano_emissao BETWEEN 2019 AND 2024 AND op.sigla_uf='BA'),ag AS (SELECT DISTINCT c.id_referencia_bacen,c.numero_ordem,c.ano_emissao,c.cnpj_agencia FROM `basedosdados.br_bcb_sicor.recurso_publico_complemento_operacao` c WHERE c.ano_emissao BETWEEN 2019 AND 2024 AND c.id_municipio='2929701' AND c.cnpj_agencia IS NOT NULL),bnb AS (SELECT o.* FROM ops o JOIN `basedosdados.br_bcb_sicor.instituicao_financeira` i ON i.cnpj_basico=o.cnpj_basico_instituicao_financeira WHERE i.nome='BCO DO NORDESTE DO BRASIL S.A.') SELECT ag.cnpj_agencia,e.cnpj,e.razao_social,e.nome_fantasia,e.id_municipio,e.sigla_uf,e.logradouro,e.numero,e.bairro,COUNT(DISTINCT ag.id_referencia_bacen) operacoes,MIN(ag.ano_emissao) primeiro_ano,MAX(ag.ano_emissao) ultimo_ano FROM ag JOIN bnb USING(id_referencia_bacen,numero_ordem) LEFT JOIN `basedosdados.br_bd_diretorios_brasil.empresa` e ON e.cnpj=ag.cnpj_agencia GROUP BY 1,2,3,4,5,6,7,8,9 ORDER BY operacoes DESC